def orfs(s, strand, min_aa=30):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        while i < len(s)-2:
            cod=s[i:i+3]
            if cod=="ATG" and start is None:
                start=i
            elif cod in ("TAA","TAG","TGA") and start is not None:
