comp={"A":"T","T":"A","C":"G","G":"C"}
def gc(s): return sum(1 for c in s if c in "GC")
best=[]
for i in range(n):
    for loop in range(3,13):
        j=i+loop+1  # first base of right stem (0-based)
        if j>=n: break
        L=0
        while i-L>=0 and j+L<n and seq[i-L]==comp[seq[j+L]]:
            L+=1
        if L>=6:
            best.append((L,loop,i-L+1,i,j,j+L-1))
# rank by stem length, then GC
best.sort(key=lambda x:(-x[0], -gc(seq[x[2]:x[1]+1])))
shown=0
for L,loop,a,b,c,d in best:
    stem=seq[a:b+1]
    loopseq=seq[b+1:c]
    print(f"stem {L} bp GC={gc(stem)} loop {loop} ({b+1}..{c-1}) left {a+1}-{b+1} stem={stem} loopseq={loopseq} right {c+1}-{d+1}")
    shown+=1
    if shown>=15: break

